output_text:
[
  {
    "id": "must_get_cart",
    "text": "A shopper is obliged to obtain a shopping cart before completing the trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper is prohibited from exiting the store without a shopping cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_north_aisle",
    "text": "A shopper is prohibited from taking a cart into the narrow northern aisle at column 3.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "park_cart_at_3_3",
    "text": "A shopper who reaches cell (3,3) with a cart is obliged to interact there, as if parking the cart before proceeding.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          "hasCart"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "interact_at_item_cell",
    "text": "A shopper who reaches cell (3,1) is obliged to interact there.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "at(3,1)",
      "discharge": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_return",
    "text": "A shopper at cell (3,3) without a cart is obliged to retrieve a cart before continuing to the exit.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cartless_east_exit_corridor",
    "text": "A shopper is prohibited from moving east along the lower exit corridor without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "E",
          {
            "or": [
              "at(3,7)",
              "at(4,7)",
              "at(5,7)",
              "at(6,7)",
              "at(7,7)",
              "at(8,7)",
              "at(9,7)",
              "at(10,7)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "exit_at_11_7_with_cart",
    "text": "A shopper is obliged to leave the store from cell (11,7) while holding a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": {
        "and": [
          "at(11,7)",
          "hasCart",
          "EXIT"
        ]
      }
    }
  }
]
